  var CFG = {
    mensajes: [
      'Cargando formulario…',
      'Un momento, por favor…'
    ],
    fondo: 'marfil',           // 'marfil' (cubre la página) | 'vidrio' (la página se ve detrás, desenfocada)
    etiqueta: 'Hotel Dorado Plaza Bocagrande',   // lo que leen los lectores de pantalla antes de «Cargando»
    intervaloMensajes: 2800,   // ms entre un mensaje y el siguiente
    porcentaje: true,          // true = el logo se dibuja con el % de carga y se ve la cifra
    retraso: 0,                // ms de espera antes de mostrarse (0 = de inmediato)
    minimoVisible: 650,        // ms mínimos en pantalla (evita parpadeos)
    salida: 'auto',            // 'auto' | 'telon' | 'enfoque' | 'rapida' | 'desvanecer' | 'cancelada' | 'inmediata'
    telonDesde: 1200,          // salida 'auto': telón (o enfoque completo con vidrio) si estuvo visible al menos esto; si no, salida rápida
    inicioRetraso: 300,        // modo inicio: en las páginas siguientes solo aparece si la carga tarda más de esto
    inicioSiempre: false,      // modo inicio: true = aparece desde el primer instante en TODAS las páginas
    ajaxUmbral: 400,           // modo ajax: solo aparece si la petición tarda más de esto
    ajaxIgnorar: null,         // modo ajax: RegExp o texto de URLs que NO activan el cargador
    navegacionRetraso: 120,    // modo navegación: espera antes de mostrarse al cambiar de página
    navegacionTiempoMax: 12000,// modo navegación: si la página no cambia (p. ej. era una descarga), se cierra
    tiempoMaximo: 45000,       // seguridad: si nadie lo cierra, se cierra solo (0 = nunca)
    zIndex: 2147483000
  };

  var SCRIPT = document.currentScript;          // para leer data-* de configuración

  /* ================================================================
   * 3) TIEMPOS (milisegundos)
   *    Con porcentaje (normal): el logo se dibuja a medida que carga.
   *    Sin porcentaje (porcentaje: false) se usa el ciclo «Trazo de oro»:
   *    0,0 s círculo fino · 0,4 s espiral hacia adentro · 1,2 s chispa
   *    · 1,8 s brillo · 2,4 s se desvanece y vuelve a empezar.
   * ================================================================ */
  var CICLO = 3000;
  var T = {
    anillo: [0, 420],          // círculo exterior (antihorario, desde arriba a la izquierda)
    grosor: [300, 950],        // los trazos pasan de finos a su grosor real
    b: [0, 960],               // trazo derecho (su inicio se calcula: sale cuando el círculo pasa por él)
    a: [420, 1200],            // espiral principal: del círculo hacia el centro
    chispa: [1200, 1800],      // chispa dorada recorriendo la espiral
    brillo: [1800, 2400],      // destello completo
    fundirAnillo: [2400, 2760],// se desvanece el círculo…
    fundirB: [2420, 2780],     // …y el trazo derecho…
    recogerA: [2440, 2960]     // …mientras la espiral se recoge hacia el centro
  };
  var LETRAS_INI = 250, LETRAS_PASO = 55, LETRAS_DUR = 460;      // DORADO PLAZA, letra por letra
  var LINEA2_INI = 820, LINEA2_PASO = 18, LINEA2_DUR = 420;      // RECEPCIÓN · HOTEL DORADO PLAZA · BOCAGRANDE
  var LINEAS = [1250, 1850];                                     // hilos dorados a los lados
  var MENSAJE_INI = 650, MENSAJE_FUNDIDO = 520;

  /* ---------- utilidades de animación ---------- */
  function c01(x) { return x < 0 ? 0 : (x > 1 ? 1 : x); }
  function tramo(t, a, b) { return c01((t - a) / (b - a)); }
  function lerp(a, b, k) { return a + (b - a) * k; }
  function eSeno(x) { return 0.5 - Math.cos(Math.PI * x) / 2; }
  function eCubica(x) { return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2; }
  function eSalida(x) { return 1 - Math.pow(1 - x, 3); }
  function eCuarta(x) { return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2; }
  function campana(x) { return Math.sin(Math.PI * c01(x)); }
  function ahora() { return (window.performance && performance.now) ? performance.now() : Date.now(); }
  function f2(n) { return Math.round(n * 100) / 100; }

  /* ---------- muestreo de los trazos (para la plumilla, la chispa y las longitudes) ---------- */
  function muestrear(d, pasos) {
    var n = d.match(/-?\d*\.?\d+(?:e-?\d+)?/g).map(Number);
    var pts = [[n[0], n[1]]], x0 = n[0], y0 = n[1], i = 2, k, t, m;
    while (i + 5 < n.length) {
      for (k = 1; k <= pasos; k++) {
        t = k / pasos; m = 1 - t;
        pts.push([
          m * m * m * x0 + 3 * m * m * t * n[i] + 3 * m * t * t * n[i + 2] + t * t * t * n[i + 4],
          m * m * m * y0 + 3 * m * m * t * n[i + 1] + 3 * m * t * t * n[i + 3] + t * t * t * n[i + 5]
        ]);
      }
      x0 = n[i + 4]; y0 = n[i + 5]; i += 6;
    }
    var acc = [0];
    for (k = 1; k < pts.length; k++) {
      acc.push(acc[k - 1] + Math.sqrt(Math.pow(pts[k][0] - pts[k - 1][0], 2) + Math.pow(pts[k][1] - pts[k - 1][1], 2)));
    }
    return { pts: pts, acc: acc, L: acc[acc.length - 1] };
  }
  function puntoEn(m, u) {                       // punto en la fracción u (0–1) del trazo
    var s = c01(u) * m.L, lo = 0, hi = m.acc.length - 1, mid;
    while (hi - lo > 1) { mid = (lo + hi) >> 1; if (m.acc[mid] < s) { lo = mid; } else { hi = mid; } }
    var a = m.pts[lo], b = m.pts[hi], seg = (m.acc[hi] - m.acc[lo]) || 1, k = (s - m.acc[lo]) / seg;
    return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k];
  }
  function perimetroElipse(rx, ry) {             // aproximación de Ramanujan (exacta a 0,01 %)
    var h = Math.pow(rx - ry, 2) / Math.pow(rx + ry, 2);
    return Math.PI * (rx + ry) * (1 + 3 * h / (10 + Math.sqrt(4 - 3 * h)));
  }
  function moverTrazo(d, dx, dy) {               // desplaza un path (comandos absolutos M/L/Q/C/Z)
    var i = 0;
    return d.replace(/-?\d*\.?\d+/g, function (v) { var r = parseFloat(v) + ((i++ % 2) ? dy : dx); return String(Math.round(r * 10) / 10); });
  }

